/**
 * The link groups of FooterSplit as cards: a glyph and the group title over its links, four across on wide
 * screens.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Group } from "../primitives/group/group";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import type { MegaGroup } from "../blocks/mega-menu.types";

export type FooterGroupCardsProps = {
  label: string;
  groups: MegaGroup[];
  landmarkLabel?: string;
};

export function FooterGroupCards({ label, groups, landmarkLabel }: FooterGroupCardsProps) {
  return (
    <Block tag="nav" aria-label={(landmarkLabel ?? label)}>
      <Box className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {(groups ?? []).map((g) => (
          <Stack key={g.id} gap="4" align="stretch" className="rounded bg-card inset-ring inset-ring-border p-6" data-testid="group">
            <Group gap="2" align="center">
              <Inline className="flex size-10 shrink-0 items-center justify-center rounded bg-muted text-foreground">
                <LucideIcon name={g.icon} size={20} />
              </Inline>
              <Text size="sm" weight="semibold">
                {g.title}
              </Text>
            </Group>
            <List className="m-0 flex list-none flex-col gap-2 p-0">
              {(g.links ?? []).map((item) => (
                <ListItem key={item}>
                  <Link href="#/" variant="muted" size="sm">
                    {item}
                  </Link>
                </ListItem>
              ))}
            </List>
          </Stack>
        ))}
      </Box>
    </Block>
  );
}
